    "id": "idea-planner",
    "slug": "idea-planner",
    "title": "Idea planner page",
    "summary": "Interactive idea planner with notes, entity approve/add/remove, filters, and save plan.",
    "sourcePath": "apps/componentLibrary/src/pageRecipes/IdeaPlannerPage.tsx",
    "exportName": "IdeaPlannerPage",
