    "title": "Search page",
    "summary": "Interactive in-app search with live query, type filters, result counts, and empty state.",
    "sourcePath": "apps/componentLibrary/src/pageRecipes/SearchPage.tsx",
    "exportName": "SearchPage",
    "targetRoute": "/search",
